{"l":2913,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"h","q":"Hvad siger man på engelsk, når man spørger en ven, hvad han hedder?","o":["What's your name?","How are you?","Where are you from?","How old are you?"],"a":"What's your name?","r":"'What's your name?' betyder hvad hedder du. 'How old are you?' spørger om alder."},
{"l":2919,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"h","q":"Hvad siger man på engelsk, når man har glemt sin blyant og vil låne en af en klassekammerat?","o":["Can I lend a pencil, please?","Can I borrow a pencil, please?","Can you borrow me a pencil?","Do I have a pencil, please?"],"a":"Can I borrow a pencil, please?","r":"Når man selv låner noget, hedder det 'borrow'. 'Lend' betyder at låne noget ud til en anden."},
{"l":2925,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"h","q":"Hvad betyder 'Let me help you.'?","o":["Hjælp mig.","Lad mig være.","Lad mig hjælpe dig.","Hjælper du mig?"],"a":"Lad mig hjælpe dig.","r":"'Let me' = lad mig."},
{"l":2931,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"h","q":"Hvad betyder 'Wait a minute! I can't find my shoes!'?","o":["Vent en time! Jeg har mine sko!","Skynd dig! Jeg kan ikke finde mine sko!","Vent lidt! Jeg vil ikke have sko på!","Vent lige! Jeg kan ikke finde mine sko!"],"a":"Vent lige! Jeg kan ikke finde mine sko!","r":"'Wait a minute' = vent lige."},
{"l":2936,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'My best friend is called Noah. He has short black hair and he wears glasses.' Hvad har Noah på?","o":["briller","hat","jakke","ur"],"a":"briller","r":"'Glasses' = briller."},
{"l":2942,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'On Sunday we visit Grandma. She makes pancakes for us.' Hvad laver bedstemor?","o":["kage","pandekager","suppe","pizza"],"a":"pandekager","r":"'Pancakes' = pandekager."},
{"l":2948,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'The dog is under the table, and the cat is on the chair.' Hvor er katten?","o":["under bordet","på bordet","på stolen","under stolen"],"a":"på stolen","r":"'On the chair' = på stolen."},
{"l":2954,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'I like summer because I can swim in the sea every day.' Hvorfor kan personen lide sommer?","o":["Det sner hver dag.","Der er jul og gaver.","Det er koldt i vandet.","Personen kan bade i havet."],"a":"Personen kan bade i havet.","r":"'Swim in the sea' = bade i havet."},
{"l":2959,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'Leo is six. His sister Ella is three years older.' Hvor gammel er Ella?","o":["ni","tre","seks","otte"],"a":"ni","r":"6 + 3 = 9."},
{"l":2965,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'We need four plates, four cups and four spoons for dinner.' Hvor mange spiser med?","o":["to","fire","tre","otte"],"a":"fire","r":"Fire af hver ting: fire personer."},
{"l":2971,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'It's Monday today. Tomorrow is my birthday!' Hvornår har personen fødselsdag?","o":["mandag","søndag","tirsdag","onsdag"],"a":"tirsdag","r":"Dagen efter mandag er tirsdag."},
{"l":2977,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'The bus stop is across the road from my house.' Hvor er busstoppestedet?","o":["i haven bag ved huset","lige ved siden af huset","langt væk fra huset","på den anden side af vejen"],"a":"på den anden side af vejen","r":"'Across the road' = på den anden side af vejen."},
{"l":2983,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'My little brother can't read yet, so I read stories to him.' Hvorfor læser personen højt for broren?","o":["Broren kan ikke læse endnu.","Broren er syg.","Broren er træt.","Broren vil ikke læse."],"a":"Broren kan ikke læse endnu.","r":"'Can't read yet' = kan ikke læse endnu."},
{"l":2988,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'There are two bedrooms, a kitchen and a living room in our flat.' Hvor mange soveværelser er der?","o":["et","to","tre","fire"],"a":"to","r":"'Two bedrooms' = to soveværelser."},
{"l":2994,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'Ali wants to be a pilot when he grows up.' Hvad vil Ali være?","o":["læge","lærer","pilot","kok"],"a":"pilot","r":"'Pilot' = pilot."},
{"l":3000,"g":5,"b":1,"cefr":"A1","role":"reinforcement","insight":"conceptual_bridge","k":"l","q":"Læs: 'The swimming pool is closed today because it's being cleaned.' Hvorfor er svømmehallen lukket?","o":["Det er helligdag.","Vandet er koldt.","Den er gået i stykker.","Den bliver gjort rent."],"a":"Den bliver gjort rent.","r":"'Being cleaned' = bliver gjort rent."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
